INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('phantasie', 2890, '1985-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dhikh0hzeca5exi4to7s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2nnp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasie', 'The Isle of Gelnor is divided by a chain of mountains into two regions. The west is the traditional domain of human and humanoid beings - with a few renegade Orcs and Lizardmen - dedicated to order and goodness. The east is inhabited by more exotic creatures - dragons, trolls and giants. These regions have been waging war throughout the history of the Great land. Since the Great invasion by the evil sorcerer Nikademus, the isle of Gelnor has been terrorized by his merciless Black Knights. To maintain their reign of terror, the Black Knights travel from town to town, demanding sacrifices and homage. You are an adventurer looking for fame and fortune, as most of them do, and you see your chance here. Those Black Knights deserves your attention no matter the costs.' FROM games WHERE igdb_id = 2890 ON CONFLICT (game_id, language_code) DO NOTHING;
