INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounty Bob Strikes Back!', 'Bounty Bob returns in this new and exciting follow-up adventure to Miner 2049er. This time around it''s even tougher than before and Bob needs your help more than ever to guide him through the mine. The mutant organisms have multiplied and over the mine entirely. making it extremely difficult to survive the hazards of the underground passageways. Using the high-powered special equipment in the twenty-five new caverns is Bob''s only hope of achieving his objective of securing the mine and defeating the plans of the evil Yukon Yohan' FROM games WHERE igdb_id = 12305 ON CONFLICT (game_id, language_code) DO NOTHING;
