INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounder', 'The player controls a tennis ball which is used to navigate courses, composed of numerous tiles, which are suspended high above ground. The ball must be bounced past walls and over enemies; coming into contact with either, or plummeting over the edge of the course, results in the loss of one of the player''s seven lives. Courses feature power squares, which push the tennis ball forward and allow longer jumps, these must be utilized to complete the course. Power squares are also used to enable the tennis ball to reach mystery spaces, tiles with question marks, which contain extra lives and bonus jumps which are used on bonus screens. Mystery spaces can also destroy the tennis ball, resulting in the loss of a life, through instant destruction or by freezing the ball in place while a missile flies across the play area and explodes.' FROM games WHERE igdb_id = 13428 ON CONFLICT (game_id, language_code) DO NOTHING;
