INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roller Coaster', 'Roller Coaster is a platform-based game which contains some strategy and puzzle elements. Uniquely it holds the claim of being the first video game to ever simulate amusement rides. Roller Coaster was released in 1985 by British video game developer Elite Systems, to overwhelmingly positive reviews. It was, for a time, one of the most popular games for the ZX Spectrum. The game takes place in and around an amusement park after closing-time. The player takes control of the park''s owner, Colonel G. Bogey. A disgruntled employee has scattered the takings all over the fairground in the form of money bags. The goal is to collect the money.' FROM games WHERE igdb_id = 22523 ON CONFLICT (game_id, language_code) DO NOTHING;
