INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('silent-service', 8825, '1985-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yj9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru9b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Service', 'Exciting World War II Submarine Action in the South Pacific by Sid Meier. 0400 hours, Tuesday 1942... BATTLE STATIONS!! BATTLE STATIONS!! Enemy convoy identified on radar!! SILENT SERVICE, The Submarine Simulation, brings exciting action, great strategy, detailed graphics and an ultra-realistic simulation of a World War II U.S. submarine in the South Pacific. SILENT SERVICE''s outstanding features include: all the critical battle stations 0 engine room, conning tower and ship''s bridge; challenging and realistic combat versus single ships and heavily escorted convoys; and an infinite variety of situations using complete maps and charts for the entire South-west Pacific and a sophisticated and realistic attack plotting system. SILENT SERVICE is the most detailed and realistic submarine simulation for home computers. Player selected "reality levels" allow the player to customize complexity, and time scaling ensures that the actions and decisions are constantly required. SILENT SERVICE provides a wide selection of historical scenarios from individual attacks to patrol missions that bring challenge and fun to both the first time player and the experienced submarine veteran. Will you, as submarine captain, select a quiet patrol sector in the Marianas Islands, or choose the dangerous waters off the coast of Japan? Is the submerged daylight periscope attack best, or do you charge in on the surface at night using only radar bearing to guide you? Do you pick off the enemy with a single torpedo shot? These decisions and many more are yours to make as you take your place among the elite ranks of the SILENT SERVICE!' FROM games WHERE igdb_id = 8825 ON CONFLICT (game_id, language_code) DO NOTHING;
