INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paradroid', 'The game is set on a spaceship viewed from a top-down perspective. The ship consists of numerous rooms and levels, each one populated by hostile robots or "droids". The player, in control of a special droid called the "Influence Device", must destroy all the other droids on the ship. Each droid (including the player) is represented as a circle around a three-digit number. The numbers roughly correspond to the droid''s "power" or "level", in that higher-numbered droids are tougher to destroy. The Influence Device is numbered "001". The primary way in which the Influence Device destroys other droids is by "linking" with them, effectively taking them over. When the player takes over another droid, the previously-controlled droid is destroyed.' FROM games WHERE igdb_id = 22518 ON CONFLICT (game_id, language_code) DO NOTHING;
