INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monty-on-the-run', 23058, '1985-12-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ljk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1pn5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monty on the Run', '"Monty Mole was imprisoned due to his coal theft in Wanted: Monty Mole, and rescued by Sam Stoat in Monty is Innocent. Now he has to get out of Britain while he still can. Like the original, the game is a flick-screen platformer with puzzly leanings. Learning the movement paths of enemies, and the timing sequence of the crushers, and working out a path across the screen by using the offered ropes and platforms. Not all parts of all screens can be accessed at once. You will need to collect money and other items along the way. Before starting the game, you must choose five items from a selection of 21 to form your ''Freedom Kit'' – correct selections are essential to complete the game, and a degree of trial and error is required to know which ones are correct." --mobygames.com' FROM games WHERE igdb_id = 23058 ON CONFLICT (game_id, language_code) DO NOTHING;
