INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-of-britain', 13383, '1985-12-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8i7u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4e2e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle of Britain', 'In Battle of Britain the player controls the RAF Fighter Command during the turning point air battle of the World War 2. You may familiarize yourself with the game by choosing to fight one day with either light or heavy enemy activity, or play the full campaign (starting 20 August 1940, limited to 30 days). The map shows the southern half of Great Britain and a small corner of France, with airfields, radar stations and cities. Fighter squadrons (18 available) need to be scrambled to intercept detected incoming Luftwaffe raids. At the end of the day a tally of losses will be displayed, followed by reinforcements allocation screen.' FROM games WHERE igdb_id = 13383 ON CONFLICT (game_id, language_code) DO NOTHING;
