INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlequest', 'The object of the game is to navigate through Groken Castle to rescue Princess Margarita. The player can push certain objects throughout the game to accomplish progress. In some rooms, the prince can only advance to the next room by aligning cement blocks, Honey Jars, Candle Cakes, and Elevator Controlling Block.' FROM games WHERE igdb_id = 48070 ON CONFLICT (game_id, language_code) DO NOTHING;
