INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('buggy-boy', 12728, '1985-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/okxjq6om6t1gi4nf2wdx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/eym778idaias8v6chujm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buggy Boy', 'Buggy Boy is a race game, but not just an ordinary race game. There are five different routes, offroad, north, east, west, south. The offroad course loops around back to the start, the others are long runs with a distinct beginning and ending. You must complete each leg before the time runs out. Along the way you can pick up all kinds of bonuses. The colored flags are 30 points each, collect all colors in the order as indicated at the top of the screen to get 1000 bonus points. There are several gates the give you 100, 250 or 500 points, and a time gate. Drive through a time gate to collect it, you receive two seconds extra time upon completing a leg. Occasionally there will be a soccer ball on the road, hit it and it will fly away and you get 2000 points. There are bridges and tunnels, be careful not to fall off the bridge into the water or crash into the tunnel wall. There also are obstacles like boulders, logs and fences. If you hit them it will cost you valuable seconds off your leg time. But if you hit a log or small stone just right, the buggy will ride on two wheels until you hit something again.' FROM games WHERE igdb_id = 12728 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 12728 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
