INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Harrier', 'Run… fly… dodge those obstacles, but return fire on wave after wave of attacking aliens. Armed with a really big gun, you have to defend yourself against the alien hordes using your wits to navigate around the screen. But watch out for those end of level bosses! Originating in the arcades, Space Harrier is a third-person rail shooter with pseudo-3D graphics, set in the same world as Fantasy Zone. The lone titular hero fights aliens with a fireball-launching cannon, which can also be used to transform the hero into a flying rocket. The protagonist is constantly in motion, but the speed of his movement can be regulated by the player.' FROM games WHERE igdb_id = 12857 ON CONFLICT (game_id, language_code) DO NOTHING;
