INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mach Rider', 'Mach Rider is a futuristic driving video game created by Nintendo. It was first released on November 21, 1985 for the Nintendo Family Computer in Japan. The game received a North American release in mid-1986 as part of the second wave of NES releases by Nintendo. On March 15, 1987 it was released in Europe and Australia. In July 2007 a modified version was released on the Wii''s Virtual Console, which allowed designed tracks to be saved.' FROM games WHERE igdb_id = 4616 ON CONFLICT (game_id, language_code) DO NOTHING;
