INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dig Dug II: Trouble in Paradise', 'DIG DUG has decided to chill out from the pressures of the real world by taking a long overdue vacation on a beautiful Caribbean island. "At last," he thinks to himself, "sun, sand, surf, and no more hassles from those miserable pests Pooka and Fygar!" Lying in a hammock between the graceful palm trees, he drifts off into a blissful dream of beautiful bikini clad native girls catering to his every wish. But just when he thinks he''s got it made in the shade, along come his troublesome enemies to turn his peaceful paradise into a tropical nightmare. Help DIG DUG rid the island of these irritating intruders and bring tranquility back to his vacation by the sea!' FROM games WHERE igdb_id = 2736 ON CONFLICT (game_id, language_code) DO NOTHING;
