INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghosts-n-goblins', 6807, '1985-07-07', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20fk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/clbt5ezssgheyvrbt4fj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghosts ''n Goblins', 'Ghosts ''n Goblins is a platform game where the player controls a knight, named Sir Arthur, who must defeat zombies, ogres, demons, cyclops, dragons and other monsters in order to rescue Princess Prin Prin, who has been kidnapped by Satan, king of Demon World. Along the way the player can pick up new weapons, bonuses and extra suits of armor that can help in this task. The game is often considered very difficult by arcade standards and is commonly regarded as one of the most difficult games ever released. The game is considered by Gametrailers.com to be the world''s second most difficult game ever made. The player can only be hit twice before losing a life (the first hit takes away Arthur''s armor, and the player must continue on in his underwear until completing the level, or finding replacement armor). If the player loses a life, he is returned to the start of the level, or the halfway point if he has managed to get that far. Furthermore, each life can only last a certain length of time (generally around three minutes), the clock being reset at the start of a level. If the clock does run out, the player instantly loses that life. After defeating the final boss, but only with the cross weapon (if the player does not have the cross weapon, they will be prompted that it is needed to defeat the boss and restart at the beginning of level 5 and must repeat round 5 and 6 again regardless if the weapon is obtained immediately or not) for the first time the player is informed that the battle was "a trap devised by Satan". The player must then replay the entire game on a higher difficulty level to reach the genuine final battle.' FROM games WHERE igdb_id = 6807 ON CONFLICT (game_id, language_code) DO NOTHING;
