INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fellowship of the Ring: A Software Adventure', 'The Fellowship of the Ring is an interactive fiction (with graphics) game based on the first volume of J.R.R. Tolkien''s novel The Lord of the Rings, describing the efforts of the Hobbits Frodo, Pippin, and Sam and their quest to bring the ring to Mount Doom. The game is divided into two parts (represented by two separate executable files: DOS version). The first part starts with Frodo at his home in the Shire, where eventually you will team up with the other Hobbits Pippin and Sam, as well as Aragorn and Gandalf. From meeting with Tom Bombadil, the Green Knight, the Balrog and ends with the Nazgul River incident. The second part of the game starts with forming of the fellowship, thus adding new team members: Boromir, Legolas, etc., until the end of the novel.' FROM games WHERE igdb_id = 10798 ON CONFLICT (game_id, language_code) DO NOTHING;
