INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spellbreaker', 'Spellbreaker is an interactive fiction computer game written by Dave Lebling and released by Infocom in 1985, the third and final game in the "Enchanter Trilogy". Like most of Infocom''s games, it was released for many of the time''s popular computer platforms, such as the Commodore 64, Atari ST and Apple II. It is Infocom''s eighteenth game. Over the course of events in the trilogy''s earlier games from 956 to 957 GUE (Enchanter and Sorcerer), the player''s character has progressed from a novice wizard possessing a few weak spells to the leader of the Circle of Enchanters. Now, in 966 GUE (ten years after the events of Enchanter), the very foundations of Magic itself seem to be failing, and the leaders of all the Guilds in the land have gathered to demand answers. In the midst of this impassioned meeting, the crowd is suddenly transformed into a group of toads and newts. Everyone present is affected except for the player and a shadowy figure who flees the hall.' FROM games WHERE igdb_id = 1949 ON CONFLICT (game_id, language_code) DO NOTHING;
