INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TwinBee', 'TwinBee is a cartoon-themed vertical-scrolling shoot ''em up game. It was the very first game to run on Konami''s Bubble System hardware. TwinBee was later re-released on PSP as part of TwinBee Portable collection, DS as part of Konami Classics Series: Arcade Hits, PC and Xbox 360 through Game Room service, and PlayStation 4, Nintendo Switch, Xbox One and PC as part of Arcade Classics Anniversary Collection.' FROM games WHERE igdb_id = 4623 ON CONFLICT (game_id, language_code) DO NOTHING;
