INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman', 3445, '1985-12-20', 58, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2v5i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/m3mvpbxqtgvzwqa48sxe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman', 'Bomberman is a robot engaged in the production of bombs. Like his fellow robots, he had been put to work in an underground compound by evil forces. Bomberman found it to be an unbearably dreary existence. One day, he heard an encouraging rumor. According to the rumor, any robot that could escape the underground compound and make it to the surface could become human. Bomberman leaped at the opportunity, but escape proved to be no small task. Alerted to Bomberman''s betrayal, large numbers of the enemy set out in pursuit. Bomberman can rely only on bombs of his own production for his defense. Will he ever make it up to the surface? Once there, will he really become human?' FROM games WHERE igdb_id = 3445 ON CONFLICT (game_id, language_code) DO NOTHING;
