INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hang-on', 6110, '1985-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ol6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scg92h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hang-On', 'Hang-On is an arcade game designed by Yu Suzuki and released by Sega in 1985. In the game, the player controls a motorcycle against time and other computer-controlled bikes. It was one of the first arcade games to use 16-bit graphics and Sega''s "Super Scaler" technology that allowed pseudo-3D sprite-scaling at high frame rates. It also introduced a motion-controlled arcade cabinet, where the player''s body movement on a large motorbike-shaped cabinet corresponds with the player character''s movements on screen, inspiring arcade games that followed and anticipating the modern motion control trend.' FROM games WHERE igdb_id = 6110 ON CONFLICT (game_id, language_code) DO NOTHING;
