INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raiders5', 'Raiders5 is a top-down maze shooter with some puzzle elements. A level consists of a single maze with a vertical design. The player controls a ship that can move in four directions. To complete a level the exit needs to be opened up before time runs out. A maze consists of two types of blocks that form walls, enemies and collectibles. The tiles for movement are coloured purple. By shooting regular, grey maze walls they disappear and orange tiles appear instead.' FROM games WHERE igdb_id = 40166 ON CONFLICT (game_id, language_code) DO NOTHING;
