INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris', 'The original version of Tetris was created by Alexey Pajitnov for the Elektronika-60 computer. It was never released commercially. It was also playable on the successor DVK-1 and DVK-2 computers, although it is unknown whether that is a different version, or simply the same code running on a different computer. Minor visual differences are present, but the gameplay is the exact same.' FROM games WHERE igdb_id = 130749 ON CONFLICT (game_id, language_code) DO NOTHING;
