INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gun-smoke', 1288, '1985-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3c5j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nr7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gun.Smoke', 'Gun.Smoke is very similar to Commando, another Capcom game, but with several differences. Whereas Commando is a run and gun game, this game is a scrolling shooter in which the screen scrolls upward automatically and players only have three ways to shoot, using three buttons for left, right, and center shooting. However, a player can also change the way the gunman shoots through button combinations. A player can still die by getting shot or struck by enemies like in Commando but improve protection by getting special items, including a horse, for protection up to three hits; boots, for speed of movement; bullets, for faster shots; and rifles, for shot length. These items are found by shooting barrels and rifles, boots, and bullets can stock up to five. It was brought to the Sega Master System in South Korea without a license by Prosoft in 1990.' FROM games WHERE igdb_id = 1288 ON CONFLICT (game_id, language_code) DO NOTHING;
