INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gi-joe-a-real-american-hero', 25981, '1985-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/i6qhct1jboyghz3za9lm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu6x6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G.I. Joe: A Real American Hero', 'Yo Joe! COBRA is up to its slimy tricks once again. They are planning world domination through mass terrorism. The team forces must unite to advance and stop the menace of COBRA in G.I. Joe. the new video game adventure from Konami! Team G.I. Joe members Duke, Road Block, Snake-Eyes, and Scarlett have their work cut out for them. They have been individually trained in specialized military areas. Snake-Eyes is a mystical martial arts master, most dangerous when he is unarmed and cornered. Road Block is a heavy machine gunner who is also adept at hand-no-hand combat. Scarlett, whose strength is military intelligence, is no wimp when it comes to kicking butt. Duke, trained in close range fighting, is looked upon as the guidance counselor. big brother. and offensive coach to the G.I. Joe unit. Together they get tough on the ruthless Cobra Commander and his sleazy Cobra Vipers and Toxo-Vipers. After attacking big cities, COBRA begins to spread mass destruction and chaos. G.I. Joe must destroy the chemical plant to rid the world of COBRA''s toxic terror tactics. They advance through to the Air Base where Cobra Commander''s dive-bonbing planes, helicopters, tanks, and legions of soldiers are ready for battle. Then it''s showtime at COBRA''s weapons plant, where the high-tech, destructive arms are being manufactured. When the weapons plant is destroyed, Cobra Commander threatens to launch powerful missiles targeted at cities all over the world. unless G.I. Joe lays down its arms. G.I. Joe, never surrendering, searches through the depths of the jungle for COBRA''s secret military base. Once they find the base, where COBRA is storing the deadly missiles, G.l. Joe fights through it to the ultimate showdown with Cobra Commander. It''s time for G.l. Joe to get down and dirty, and show COBRA how tough they really are. Join the ranks of a fearless team - G.I. Joe. a real American hero!' FROM games WHERE igdb_id = 25981 ON CONFLICT (game_id, language_code) DO NOTHING;
