INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where in the World Is Carmen Sandiego?', 'Woldwide crime wave! Acme Detective Agency hot on the trail of master thief Carmen Sandiego and her henchmen. Wanted: Detective to locate and capture Carmen and her gang. Must be hard working, independent, fun seeking individual willing to travel the world. No experience necessary. - Digitised graphics - Hundreds of cases - More animated sequinces - Play in 5 languages Don''t forget your World Almanac. It is a gumshoe''s best friend.' FROM games WHERE igdb_id = 251 ON CONFLICT (game_id, language_code) DO NOTHING;
