INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest II: Romancing the Throne', 'King''s Quest II: Romancing the Throne is an adventure game in the King''s Quest series. Players control King Graham, now ruler of Daventry, as he searches for a bride in the land of Kolyma. The game follows Graham''s quest to rescue a maiden named Valanice, who is imprisoned in a quartz tower by an evil witch. Players guide Graham through various locations, solving puzzles and overcoming obstacles using inventory items and interaction with characters. The game world draws inspiration from fairy tales and folklore, featuring encounters with classic characters and creatures. King''s Quest II expands on the gameplay established in the first game, offering a larger world to explore and more complex puzzles. As the second installment in the series, it continues the story of Graham and introduces elements that would become important to the broader King''s Quest narrative, including the character of Valanice, Graham''s future queen.' FROM games WHERE igdb_id = 852 ON CONFLICT (game_id, language_code) DO NOTHING;
