INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathstar', 'DeathStar is a Sinistar clone featuring space combat across endlessly scrolling environments where players pilot a ship that rotates in sixteen directions while moving forward continuously. Players shoot planetoids to release crystals needed to create starbombs, competing against AI workers and warriors who mine the same resources to construct the titular DeathStar vessel. Once twenty crystals are delivered by workers, the DeathStar appears and must be destroyed using accumulated starbombs, with each hit removing one piece until all twenty are eliminated for 15,000 bonus points. The game progresses through four zones—Worker, Warrior, Planetoid, and Void—each introducing slight variations in enemy composition and resource availability, with a radar display tracking all objects and opponents throughout gameplay.' FROM games WHERE igdb_id = 94808 ON CONFLICT (game_id, language_code) DO NOTHING;
