INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadowfire', 'General Zoff is holding Ambassador Kryxix captive in his spaceship. Plans for a new type of spaceship are hidden in a micro-disc embedded in the Ambassador''s spine. If Zoff had the plans, the empire would be in great danger, and it is only a matter of time until his inquisitors will discover them. The Emperor has assembled the so-called "enigma team", a group of six reckless mercenaries, to take care of the situation.' FROM games WHERE igdb_id = 13034 ON CONFLICT (game_id, language_code) DO NOTHING;
