INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Section-Z', 'Section-Z is a side-view shoot-''em-up by Capcom originally released as a coin-operated video game in 1985. A home version was released for the Nintendo Entertainment System in 1987. The original coin-op game is included in Capcom Classics Collection Vol. 1 for PlayStation 2 and Xbox.' FROM games WHERE igdb_id = 9755 ON CONFLICT (game_id, language_code) DO NOTHING;
