INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wishbringer', 'Wishbringer: The Magick Stone of Dreams is an interactive fiction computer game written by Brian Moriarty and published by Infocom in 1985. It was intended to be an easier game to solve than the typical Infocom release and provide a good introduction to interactive fiction for inexperienced players, and was very well received.' FROM games WHERE igdb_id = 1950 ON CONFLICT (game_id, language_code) DO NOTHING;
