INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alice in Wonderland', 'Alice in Wonderland is an adventure platformer based upon the two Alice books by Lewis Carrol and created using the same engine as Below the Root. However, whereas that game had more of a focus on role playing, Alice has more of a focus on puzzle solving.' FROM games WHERE igdb_id = 12250 ON CONFLICT (game_id, language_code) DO NOTHING;
