INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones and the Temple of Doom', 'As Indy, the player must complete several cycles of the following three types of levels: 1.Mine level: Whip your way through a mine in order to free children that are held captive. Use your whip to swing across chasms, climb ladders, ride along conveyor belts and defend yourself against attacks from Thuggee guards, bats, snakes and the fireball-throwing Mola ram. Escape with the mine cart after you''ve freed all children. 2.Mine cart level: Pick the right route through a network of tracks while riding in a mine cart. Avoid potholes, broken tracks & guards in carts and safely reach the end of the track. 3.Temple level: Make your way to the altar and grab the Sankara stone while Mola Ram, bats and Thuggee guards attack you. Watch out for that lava.' FROM games WHERE igdb_id = 12156 ON CONFLICT (game_id, language_code) DO NOTHING;
