INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teddy Boy', 'In Teddy Boy you must scramble from maze to maze - each more magnificent than the one before it - bumping off bugs, guppies, snails, dominos and more as you go. Grab precious points for tennis shoes, teddy bears, snails, and other identifiable objects. And try to avoid the ugly Den Den, a snapping dragon head. Or you''ll be forced to wake up to reality.' FROM games WHERE igdb_id = 46100 ON CONFLICT (game_id, language_code) DO NOTHING;
