INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Way of the Exploding Fist', 'Discover Kung-Fu: The Way of the Exploding Fist (also known as Way of the Exploding Fist, The Way of the Exploding Fist), an excellent game of 1985 runnable on Amstrad CPC system. With side view, fixed / flip-screen perspective, the publisher Melbourne House had wonderful ideas around fighting, martial arts.' FROM games WHERE igdb_id = 13045 ON CONFLICT (game_id, language_code) DO NOTHING;
