INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frankie Goes to Hollywood', 'Playing a thoroughly drab, mundane and predictable character, your aim is to become interesting enough to reach the Pleasuredome. After discovering a gruesome murder, your interest in something greater than the routine of 80s Liverpool is awoken. You explore the streets and houses in the search of a way out. The main basis of the game involves picking up objects and using them in the correct way - most objects have more than one potential use, and misusing them is the only way the game can be lost. There are several sub-games along the way, including shoot ''em ups, a maze and a jigsaw puzzle.' FROM games WHERE igdb_id = 22519 ON CONFLICT (game_id, language_code) DO NOTHING;
