INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hardball', 12136, '1985-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wya.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ozsmnxjs311s8cdpke6z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HardBall!', 'Play is controlled with a joystick or arrow keys and an action button. One of the four cardinal directions is used to choose the pitch, and again to aim it towards low, high, inside (towards batter), or outside (away from batter). The same directions are used to aim the swing when batting. When fielding after a hit, the defensive player closest to the ball will flash to show it is the one currently under control. The four directions are then used to throw to one of the four bases. The game incorporates a pitcher perspective, often used in MLB broadcasts. There are also managerial options available. The player has a selection of pitchers to choose from. Each team member has his own statistics that affect his performance, and can be rearranged as desired. Prior to HardBall!s release, there were managerial baseball games available, such as Micro League Baseball but HardBall! was the first to integrate that aspect with the arcade control of the game action itself.' FROM games WHERE igdb_id = 12136 ON CONFLICT (game_id, language_code) DO NOTHING;
