INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Games II', 'Sure Summer Games was great. but why stop there? Summer Games II will take you even farther with eight challenging. new events. You and up to seven other contestants can compete in your favorite individual event or go for it all in the grand competition. Some events. like cycling. rowing and fencing even challenge you with realistic head-to-head competition. First. decide which oi the 18 different countries you‘re going to represent. Then. in true Olympic fashion. you will need the proper strategy and mental toughness. not just speed and agility to excel in each of the eight events. That’s why we included a feature that lets you practice each event until you''re ready for the real competition Remember. it’s not too early to get ready for 1988. the the right diet, proper training and lots of practice you just might make it- In the meantime, put on your sweatsuit. grab that joystick and let Summer Games ll give you eight new ways to Go For The Gold! -Includes Cycling, Fencing. Kayaking. Triple Jump. Rowing. High Jump. Javelin and Equestrian Events -Opening. Closing and Awards Ceremony With National Anthems -Compete Against The Computer or Your Friends -Individual and Head-To-Heed Competition -One to Eight Players' FROM games WHERE igdb_id = 22524 ON CONFLICT (game_id, language_code) DO NOTHING;
