INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer', 'Experience the first ever football game for the NES. Enjoy ''real football'' as you direct your team up and down the field. Pick from seven international teams—USA, Great Britain, France, Germany, Brazil, Japan, and Spain—and perform all the kickoffs, throw-ins, goal kicks, and corner kicks seen in a real friendly match. You can choose the skill level of the opposing team on a scale from one to five, so as your team improves, so do your opponents. Select a computer team or play against a friend. You even choose the length of the match, and as time ticks down, do your best to score the winning goal!' FROM games WHERE igdb_id = 86375 ON CONFLICT (game_id, language_code) DO NOTHING;
