INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Computer People', 'Little Computer People is a social simulation game representing a fully furnished house on a computer. This "House on a Disk" is based on the theory that every computer has an "occupant" (i.e. Little Computer People - LCP), which can be made visible by providing accommodation. Every computer should have a different LCP, who is usually accompanied by a dog as a pet.' FROM games WHERE igdb_id = 12179 ON CONFLICT (game_id, language_code) DO NOTHING;
