INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Track & Field', 'A sports game, port of the arcade game Track & Field. It was later released in Europe as Track & Field in Barcelona in 1992, in the light of the 1992 Summer Olympics, earlier versions were simply known as Track & Field. The opening song for the NES version is the Chariots of Fire theme by Vangelis (which was also used in the arcade version''s high score screen).' FROM games WHERE igdb_id = 266659 ON CONFLICT (game_id, language_code) DO NOTHING;
