INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fairlight', 12995, '1985-12-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6884.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scylnn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairlight', 'The player controls an adventurer named Isvar that can be moved in a castle which is not only three-dimensional isometric view, but realistic in terms of the way objects behave. Each object has its own physical properties and resultant characteristics in terms of how much else can be carried alongside it. Certain objects have special uses (e.g. keys open certain doors), and there is a puzzle element to the game to discover how some of these objects relate to the world in order to help the player solve the game. In addition to carrying objects, they could also be stacked on top of each other to enable Isvar to climb up to rooms above him or to reach important objects perched high above on platforms. There are also a number of secret areas in the castle that are not visually obvious to the player and can only be discovered through exploration. During Isvar''s exploration of the castle he is accosted by its guards and monsters - trolls, monks, guards, tornadoes, man-eating plants, bubbles, etc. all of which weaken Isvar''s energy. The castle also contains food and magical potions which will restore his health. In addition, certain game objects can affect the enemies, (by either killing them, distracting them, or freezing them, depending on the object and the type of enemy they are used upon) Once defeated in combat a guard disappears leaving only his helmet behind. Helmets can be picked up and carried by Isvar, and placed somewhere else out of harms way (or into the path of a tornado, that destroys any object it touches). If Isvar leaves the room, the guard will regenerate from the helmet.' FROM games WHERE igdb_id = 12995 ON CONFLICT (game_id, language_code) DO NOTHING;
