INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commando', 'Several levels await your super-tough Commando in this arcade conversion. Armed with only a standard rifle and a few grenades you must take on hordes of enemies. Some are wandering around in the open, while others have picked out hiding places, which you must approach from certain angles. Trees, rivers and bridges create a varied combat-like terrain and must be incorporated into your thinking. Extra grenades can be collected, and will definitely be required, as they allow you to kill from distance and thus avoid some enemy shots.' FROM games WHERE igdb_id = 5668 ON CONFLICT (game_id, language_code) DO NOTHING;
