INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boulder Dash II: Rockford''s Revenge', 'In part two of the "Boulder Dash" series, game design hasn''t changed compared to part one, so you still have to mine diamonds while avoiding falling rocks and cave monsters of all sorts. As in part one, later levels become more difficult because many puzzle elements are added.' FROM games WHERE igdb_id = 26217 ON CONFLICT (game_id, language_code) DO NOTHING;
