INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja JaJaMaru-kun', 'The game stars the brother of Ninja-kun (from Ninja-Kid). Princess Sakura has been kidnapped by Damazu-Dayuu, and because Ninja-Kun is away on a journey, the task falls to young JaJaMaru-kun. In the game, the player starts with three lives and can only run, jump and throw shurikens. The game is divided into stages, each with four floors and eight enemies. Sakura-Hime and Damazu are placed, unreachable, at the top of the screen. Enemies use various projectiles, one of which will cause the player to lose a life. If JaJaMaru-kun lands on top of an enemy, it will simply be temporarily stunned and vice versa. Once an enemy is defeated and offscreen, a spirit will appear and ascend to the top of the screen. It can be collected before it has disappeared to receive points, which vary depending on the enemy. Sakura will sometimes drop petals that the player can collect, and Damazu will sometimes run around, dropping bombs. To advance to the next stage, the player must defeat all eight enemies by using shurikens. Some bricks yield items. They include: A cart that temporarily makes JaJaMaru-kun invincible and faster. Projectiles and enemies will also be destroyed if touched. A bottled substance that makes JaJaMaru temporarily invincible and able to walk through enemies. A red ball that increases speed. Bombs (which must be avoided). Coins that yield various amounts of points. An extra life. If all three types of power-ups are collected, Gamapa-kun, a giant frog, will be summoned, which is completely invincible and able to eat all enemies. If three of Sakura''s petals are collected, the player will go to a bonus stage in which JaJaMaru-kun is on the bottom and Damazu at the top. Damazu drops bombs, and the player throws shurikens upward. If the player manages to hit Damazu, bonus points are awarded. If the JaJaMaru-kun is hit by a bomb, he goes on to the next stage. Initially the game was released exclusively in Japan, but it came to the rest of the world for the first time in 2007 as part of the Wii virtual console, as well as for Nintendo Switch Online in 2021.' FROM games WHERE igdb_id = 48455 ON CONFLICT (game_id, language_code) DO NOTHING;
