INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('city-connection', 4610, '1985-07-01', 49, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7d9k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ksc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Connection', 'City Connection is a 1-2 player comedic racing adventure platform game in which you control a car that can never be stopped. The object of the game is to drive through a series of cities and paint every part of the roads in each city as proof of your visit to that city. City Connection was remarkable for its time in that each location had its own background and music which was a variation on the main theme of the game. There are twelve locations: Manhattan, the Grand Canyon, Easter Island, Paris, Neuschwanstein Castle, London, Sydney, Egyptian temples, and cities in India, Holland, China and Japan.' FROM games WHERE igdb_id = 4610 ON CONFLICT (game_id, language_code) DO NOTHING;
